const BASE_URL = "https://altadefinizione.autos";
const PROVIDER_ID = "altadefinizione";
async function providerText(url) { const response = await fetch(url); if (!response.ok) throw new Error(`HTTP ${response.status}`); return response.text(); }
function itemType(url, title) { const value = `${url} ${title}`.toLowerCase(); return value.includes("serie") || value.includes("series") || value.includes("tv") ? "TvSeries" : value.includes("anime") ? "Anime" : "Movie"; }
function itemsFromHTML(html) { return parseHTML(html, "article, .card, .movie, .film, .item, .post").map((node, index) => { const title = String(node.text || "").replace(/\s+/g, " ").trim().slice(0, 180); const url = node.href || ""; return { id: url || String(index), title, type: itemType(url, title), url, poster: node.dataSrc || node.src || null }; }).filter(item => item.title && item.url); }
function sectionURL(sectionKey) { return sectionKey && sectionKey.startsWith("$mainUrl") ? BASE_URL + sectionKey.slice(8) : sectionKey || BASE_URL; }
async function getMainPage(page, sectionKey) { return { items: itemsFromHTML(await providerText(sectionURL(sectionKey))), hasNextPage: false }; }
async function search(query) { return itemsFromHTML(await providerText(`${BASE_URL}?s=${encodeURIComponent(query)}`)); }
async function load(url) { return null; }
async function loadLinks(data) { const value = typeof data === "string" ? tryJSON(data) : data; return value && value.url ? [{ name: PROVIDER_ID, url: value.url, type: "M3U8" }] : []; }
